func checkPartialPayment(tx *Payment) (bool, error) {
	if tx.DeliverMin == nil {
		return true, nil
	}

	if tx.Flags == 0 {
		return false, ErrPartialPaymentFlagRequired
	}

	if !types.IsFlagEnabled(tx.Flags, tfPartialPayment) {
		return false, ErrPartialPaymentFlagRequired
	}

	return true, nil

}
